def shapes(g):
    # connected components of nonzero cells (4-conn)
    seen=set(); res=[]
    for i in range(len(g)):
        for j in range(len(g[0])):
            if g[i][j] and (i,j) not in seen:
                st=[(i,j)]; comp=[]
                while st:
                    a,b=st.pop()
                    if (a,b) in seen or not(0<=a<len(g) and 0<=b<len(g[0])) or g[a][b]==0: continue
                    seen.add((a,b)); comp.append((a,b))
                    for dx,dy in((1,0),(-1,0),(0,1),(0,-1)): st.append((a+dx,b+dy))
                res.append(comp)
    return res

def norm(cells):
    rs=[a for a,b in cells]; cs=[b for a,b in cells]
    r0,c0=min(rs),min(cs)
    pat=tuple(sorted((a-r0,b-c0) for a,b in cells))
    return tuple(pat), r0, c0, len(cells)

def f(inp):
    comps=shapes(inp)
    info={}
    for c in comps:
        pat,r0,c0,nz=norm(c)
        key=(inp[c[0][0]][c[0][1]],pat)
        info.setdefault(key,[c,r0,c0,nz]).append((c,r0,c0,nz))
    # anchor color = color with >=2 instances; keep lower instance
    out=[[0]*len(inp[0]) for _ in range(9)]
    used=[]
    for (col,pat),lst in info.items():
        if col==2: continue
        best=max(lst,key=lambda t:t[1])  # lower instance wins
        # others of same pattern/color merged (deleted)
        used.append((col,best[1],best[2],best[3]))
    # sort by size desc -> larger bottom
    used.sort(key=lambda t:-t[3])
    anchor=used[-1]          # largest (or last) = bottom
    anc_col,anc_r,anc_c,anz=anchor
    for r in range(9):
        for c in range(15):
            if inp[anc_r+r][anc_c+c]==anc_col: out[r][c]=anc_col
    # others adjacent above if smaller, else below
    others=[u for u in used if u!=anchor]
    for col,rt,cc,nz in others:
        if nz<anz: tr=anc_r-3
        else: tr=anc_r+3
        for r in range(tr,tr+3):
            for c in range(cc,cc+3):
                if inp[rt+r][cc+c]==col: out[r][c]=col
    return out

