import numpy as np
def comps(g):
    g=np.array(g); seen=np.zeros_like(g,bool); res=[]
    for i in range(g.shape[0]):
        for j in range(g.shape[1]):
            if g[i,j] and not seen[i,j]:
                col=g[i,j]; st=[(i,j)]; cells=[]
                while st:
                    y,x=st.pop()
                    if 0<=y<g.shape[0] and 0<=x<g.shape[1] and g[y,x]==col and not seen[y,x]:
                        seen[y,x]=True; cells.append((y,x))
                        st+= [(y+1,x),(y-1,x),(y,x+1),(y,x-1)]
                ys=[c[0] for c in cells]; xs=[c[1] for c in cells]
                rs=(min(ys),max(ys)); cs=(min(xs),max(xs))
                res.append((int(col),cells,rs,cs))
    return res
