    g=np.array(g); H,W=g.shape; seen=np.zeros((H,W),bool); res=[]
    for i in range(H):
        for j in range(W):
            if g[i,j]!=0 and not seen[i,j]:
                col=int(g[i,j]); st=[(i,j)]; cells=[]
                while st:
                    y,x=st.pop()
                    if 0<=y<H and 0<=x<W and g[y,x]==col and not seen[y,x]:
                        seen[y,x]=True; cells.append((y,x))
                        st.extend([(y+1,x),(y-1,x),(y,x+1),(y,x-1)])
                res.append((col,cells))
    return res

